require parquet

require icu

test-env DUCKLAKE_CONNECTION {TEST_DIR}/{UUID}.db

test-env DATA_PATH {TEST_DIR}

statement ok
ATTACH 'ducklake:{DUCKLAKE_CONNECTION}' AS ducklake (DATA_PATH '{DATA_PATH}/many_inserts_transaction/')

statement ok
use ducklake

statement ok
BEGIN;

statement ok
CREATE TABLE integers(i INTEGER);

statement ok
INSERT INTO integers SELECT 1 FROM range(10);

statement ok
INSERT INTO integers SELECT 1;

statement ok
INSERT INTO integers SELECT 2;

statement ok
